import base64, pathlib, sys

def dec(s): return base64.b64decode(s).decode()

OPS = [
    ('replace', 'lib/services/manga/manga_favorite_lifecycle_service.dart', 'ICAvLy8gUHJlZmVyIGNhY2hlZCBjaGFwdGVyIHN1bW1hcmllczsgYSBvbmUtdGltZSBiYWNrZmlsbCBydW5zIG9ubHkgZm9yCiAgLy8vIGZhdm9yaXRlcyB3aXRob3V0IGEgcm93LiBSZW1vdGUgZmFpbHVyZXMgbmV2ZXIgZm9yY2UgYSBzeW5jaHJvbm91cyBsb2FkLg==', 'ICAvLy8gUHJlZmVyIGNhY2hlZCBjaGFwdGVyIHN1bW1hcmllczsgYSBmYXZvcml0ZSB3aXRob3V0IGEgcm93IGdldHMKICAvLy8gYSBiYWNrZ3JvdW5kIGJhY2tmaWxsIHNjaGVkdWxlZCAoZml4NCkg4oCUIHRoZSByZWFkIGl0c2VsZiBuZXZlcgogIC8vLyByZXBhaXJzIGl0IGlubGluZS4gUmVtb3RlIGZhaWx1cmVzIG5ldmVyIGZvcmNlIGEgc3luY2hyb25vdXMgbG9hZC4='),
    ('replace', 'lib/services/manga/manga_favorite_lifecycle_service.dart', '', ''),
    ('replace', 'test/services/manga/manga_favorite_lifecycle_service_test.dart', '', ''),
]

def main():
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    for kind, rel, old, new in OPS:
        p = root / rel
        text = p.read_text()
        if kind == "replace":
            old, new = dec(old), dec(new)
            n = text.count(old)
            if n != 1:
                raise SystemExit(f"ANCHOR FAIL {rel}: found {n} (need 1)")
            text = text.replace(old, new)
        elif kind == "append":
            snippet = dec(old)
            text = text.rstrip("\n") + "\n" + snippet
        else:
            raise SystemExit(f"unknown op {kind}")
        p.write_text(text)
        print(f"applied {kind}: {rel}")
    print("ALL ANCHORS OK")




if __name__ == "__main__":
    main()
